import{_ as n,l as o,o as e,c as s,v as r,p as l,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"字符串哈希","description":"","frontmatter":{"title":"字符串哈希","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/string-hashing.md","filePath":"cs/string-hashing.md","lastUpdated":1789023840000}'),c={name:"cs/string-hashing.md"};function f(m,a,_,u,b,B){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="字符串哈希" tabindex="-1">字符串哈希 <a class="header-anchor" href="#字符串哈希" aria-label="Permalink to &quot;字符串哈希&quot;">​</a></h1><div class="epigraph"><p>把串看成 $b$ 进制整数模素数；子串哈希用前缀一次减一次乘，相等则以高概率当相等。</p><footer>—— 据 Karp and Rabin, Efficient Randomized Pattern-Matching Algorithms, IBM J. Res. Develop. 1987；Cormen, Leiserson, Rivest and Stein 第 32 章整理</footer></div><p><a href="/cs/palindromic-tree">上一课</a> 与 <a href="/cs/suffix-automaton">SAM</a>、<a href="/cs/suffix-array">SA</a> 都是确定性索引，空间或预处理不菲。只需比较若干子串是否相等时，滚动哈希期望 \\(O(1)\\)。<a href="/cs/prefix-sum-difference">前缀和</a> 的形状几乎相同。本课不建 fail。缺口是多项式哈希 / Karp–Rabin：前缀 \\(H[i]\\)，子串 \\([l,r)\\) 为 \\(H[r]-H[l]\\cdot b^{r-l}\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素比子串 \\(\\Theta(长度)\\)。哈希：选底 \\(b\\) 与模 \\(M\\)（或双模），碰撞概率约 \\(\\Theta(q^2/M)\\) 于 \\(q\\) 次比较（生日）。缺口不是通用散列族全文（后课），而是<strong>串上的滑动与前缀</strong>，使模式匹配、LCP 二分、去重期望变快。</p><p><span class="marginnote">Karp–Rabin 1987。模 \\(2^{64}\\) 自然溢出不是素数域，对抗输入可打；教学合同写随机模或双质数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预处理 \\(H\\) 与幂 \\(p[i]=b^i\\)。比较：哈希相等再可选逐字符验证（确定性保险）。滚动：窗口右移减最左字符加最右。KMP 确定性线性；KR 期望线性、实现短。</p>',8)),(e(),l(h,null,{default:t(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E4%B8%B2%20S%22%5D%20--%3E%20H%5B%22%E5%89%8D%E7%BC%80%E5%93%88%E5%B8%8C%22%5D%0A%20%20H%20--%3E%20SUB%5B%22H%5Br%5D%20-%20H%5Bl%5D%20*%20b%5E%7Br-l%7D%22%5D%0A%20%20SUB%20--%3E%20EQ%5B%22%E7%9B%B8%E7%AD%89%3F%20%E9%AB%98%E6%A6%82%E7%8E%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与后缀数组：哈希可二分 LCP（每次中点比哈希），期望 \\(O(|P|\\log n)\\) 类，常数小；最坏碰撞要承认。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>必须固定一种下标与 \\(b^{len}\\)。溢出与负差要加 \\(M\\)。不要把哈希当加密；本课是数据结构加速。字母映射成 \\(1..|\\Sigma|\\)，避免前导零歧义。</p><p>下一课 Rope 处理的是可编辑大串，不是哈希；编辑会让前缀 \\(H\\) 失效，除非树节点存哈希——那是结合。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明通用散列全部定理。完美散列给静态键集零碰撞，后单元。对抗哈希要用随机种子，合同写期望。</p><p>后课默认：静态子串相等可用哈希。可持久大串编辑用 Rope。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多项式哈希：前缀 \\(O(n)\\)，子串 \\(O(1)\\)，期望无碰撞。</li><li>模与底要随机化；可验证。</li><li>可编辑串结构是 Rope。</li><li>出处：Karp and Rabin, 1987；Cormen et al. 第 32 章。</li></ul>',9))])}const S=n(c,[["render",f]]);export{g as __pageData,S as default};
